def porta_nei_layout(apps, schema_editor):
    """Ogni grafico stava in una pagina: ora la pagina lo elenca nella sua disposizione."""
    Grafico, Pagina = apps.get_model("grafici", "Grafico"), apps.get_model("grafici", "Pagina")
    for g in Grafico.objects.exclude(pagina=None).order_by("pk"):
        p = Pagina.objects.get(pk=g.pagina_id)            # riletta ogni volta: una copia vecchia cancellerebbe i grafici di prima
        layout = dict(p.layout or {})
        voci = list(layout.get("widget", []))
        if f"g:{g.pk}" not in [v.get("id") for v in voci if isinstance(v, dict)]:
            voci.append({"id": f"g:{g.pk}"})
        layout["widget"] = voci
        layout["nascosti"] = [i for i in layout.get("nascosti", []) if i != f"g:{g.pk}"]
        p.layout = layout
        p.save(update_fields=["layout"])


